html=r'''<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Logs e erros — MASTER</title><style>*{box-sizing:border-box}body{margin:0;font:14px Arial,sans-serif;background:#f4f7fb;color:#172033}.w{max-width:1240px;margin:auto;padding:20px}.hero,.panel{background:#fff;border:1px solid #dfe6ef;border-radius:18px;padding:18px}.hero{display:flex;justify-content:space-between;gap:12px;align-items:flex-start}.hero h1{margin:0 0 6px;font-size:24px}.muted{color:#69788d}.btn{border:0;border-radius:10px;padding:11px 14px;font-weight:800;cursor:pointer}.primary{background:#1764e8;color:white}.soft{background:#eef3f9;color:#30445f}.danger{background:#c62828;color:#fff}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin:14px 0}.stat{background:#fff;border:1px solid #e0e7f0;border-radius:14px;padding:14px}.stat b{display:block;font-size:25px}.stat.err b{color:#c62828}.stat.warn b{color:#a65c00}.filters{display:grid;grid-template-columns:1.5fr repeat(5,minmax(120px,.7fr));gap:8px;margin-bottom:12px}input,select{width:100%;height:42px;border:1px solid #ccd7e5;border-radius:10px;padding:0 10px;background:#fff}.quick{display:flex;gap:7px;flex-wrap:wrap;margin-bottom:12px}.chip{border:1px solid #d8e1ec;background:#fff;border-radius:999px;padding:8px 11px;cursor:pointer;font-weight:700}.chip.active{background:#172d52;color:#fff}.list{display:grid;gap:9px}.row{border:1px solid #e0e7f0;border-radius:14px;background:#fff;padding:13px}.row.error{border-left:5px solid #d32f2f}.row.warning{border-left:5px solid #e28a00}.row.action{border-left:5px solid #1764e8}.top{display:flex;gap:10px;align-items:flex-start;justify-content:space-between}.title{font-weight:850;font-size:15px}.meta{color:#718095;font-size:12px;margin-top:5px;display:flex;gap:8px;flex-wrap:wrap}.badge{font-size:10px;padding:3px 7px;border-radius:999px;background:#eef2f7;color:#526176}.badge.open{background:#fff0f0;color:#a21f1f}.badge.resolved{background:#eaf8ef;color:#17643a}.msg{margin-top:8px;white-space:pre-wrap;overflow-wrap:anywhere}.details{display:none;margin-top:10px;background:#111a29;color:#dbe7fa;border-radius:10px;padding:11px;white-space:pre-wrap;overflow-wrap:anywhere;font:12px/1.5 monospace}.actions{display:flex;gap:6px;flex-wrap:wrap;margin-top:9px}.empty{padding:30px;text-align:center;color:#748298}.notice{margin-top:10px;background:#edf5ff;border:1px solid #d1e2fa;border-radius:11px;padding:10px;color:#2c5283}.auto{font-size:12px;color:#5f6f82;margin-top:7px}@media(max-width:980px){.filters{grid-template-columns:1fr 1fr 1fr}.stats{grid-template-columns:1fr 1fr}}@media(max-width:600px){.w{padding:12px}.hero{display:block}.hero .btn{margin-top:10px;width:100%}.filters{grid-template-columns:1fr}.stats{grid-template-columns:1fr 1fr}.top{display:block}}</style></head><body><main class="w"><section class="hero"><div><h1>🧾 Logs e erros do sistema</h1><div class="muted">Central do MASTER para acompanhar alterações, falhas e problemas do WhatsApp.</div><div class="notice">Os registros de erro ficam guardados para consulta. Senhas, tokens e chaves são protegidos e não aparecem nos logs.</div><div class="auto">Atualização automática a cada 30 segundos.</div></div><button class="btn primary" id="refresh">↻ Atualizar agora</button></section><section class="stats"><div class="stat err"><b id="open">—</b><span>Erros em aberto</span></div><div class="stat"><b id="actions">—</b><span>Alterações hoje</span></div><div class="stat warn"><b id="errors">—</b><span>Erros detectados hoje</span></div><div class="stat err"><b id="wa">—</b><span>Falhas WhatsApp 24h</span></div></section><section class="panel"><div class="quick"><button class="chip active" data-kind="all">Tudo</button><button class="chip" data-kind="error">Somente erros</button><button class="chip" data-kind="action">Alterações</button><button class="chip" data-kind="warning">Avisos</button></div><div class="filters"><input id="search" placeholder="Pesquisar erro, ação, usuário, igreja..."><select id="church"><option value="">Todas as igrejas</option></select><select id="severity"><option value="all">Todas severidades</option><option value="critical">Crítico</option><option value="error">Erro</option><option value="warning">Aviso</option><option value="info">Informação</option></select><select id="status"><option value="all">Todos status</option><option value="open">Em aberto</option><option value="resolved">Resolvido</option><option value="done">Concluído</option></select><select id="days"><option value="1">24 horas</option><option value="7">7 dias</option><option value="30" selected>30 dias</option><option value="90">90 dias</option><option value="365">1 ano</option></select><button id="apply" class="btn soft">Consultar</button></div><div id="list" class="list"><div class="empty">Carregando logs...</div></div></section></main><script>const token=localStorage.getItem('escala-facil.auth-token')||'',H={'Content-Type':'application/json',Accept:'application/json',...(token?{Authorization:'Bearer '+token}:{})},$=x=>document.getElementById(x);let kind='all',busy=false;function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]))}async function api(b){const r=await fetch('/api/master-system-logs.php',{method:'POST',credentials:'include',headers:H,body:JSON.stringify(b)});let j={};try{j=await r.json()}catch{}if(!r.ok||j.error)throw new Error(j?.error?.message||'Falha ao consultar logs');return j.data}function dt(x){if(!x)return'—';const d=new Date(String(x).replace(' ','T'));return isNaN(d)?x:d.toLocaleString('pt-BR')}function kindName(x){return x==='error'?'Erro':x==='warning'?'Aviso':x==='action'?'Alteração':'Informação'}function render(items){$('list').innerHTML=items.length?items.map((x,i)=>`<article class="row ${esc(x.kind)}"><div class="top"><div><div class="title">${x.kind==='error'?'⚠️ ':x.kind==='action'?'✏️ ':'ℹ️ '}${esc(x.title||x.action||'Evento')}</div><div class="meta"><span>${esc(dt(x.created_at))}</span><span class="badge">${esc(kindName(x.kind))}</span><span class="badge">${esc(x.source||'sistema')}</span>${x.status?`<span class="badge ${esc(x.status)}">${esc(x.status==='open'?'EM ABERTO':x.status==='resolved'?'RESOLVIDO':'CONCLUÍDO')}</span>`:''}${x.occurrences>1?`<span class="badge">${x.occurrences} ocorrências</span>`:''}</div></div><div class="meta">${x.igreja_nome?`⛪ ${esc(x.igreja_nome)}`:''}${x.user_name?` · 👤 ${esc(x.user_name)}`:''}</div></div><div class="msg">${esc(x.message||'')}</div><div class="actions"><button class="btn soft" onclick="toggle(${i})">Ver detalhes</button>${x.resolvable&&x.status==='open'?`<button class="btn primary" onclick="resolveLog('${esc(x.native_id)}')">Marcar resolvido</button>`:''}${x.resolvable&&x.status==='resolved'?`<button class="btn soft" onclick="reopenLog('${esc(x.native_id)}')">Reabrir</button>`:''}</div><pre class="details" id="d${i}">${esc(JSON.stringify({ação:x.action,origem:x.source,usuário:x.user_name,igreja:x.igreja_nome,url:x.url,método:x.http_method,http:x.http_status,detalhes:x.details,nota_resolução:x.resolution_note},null,2))}</pre></article>`).join(''):'<div class="empty">Nenhum registro encontrado com esses filtros.</div>'}window.toggle=i=>{const e=$('d'+i);e.style.display=e.style.display==='block'?'none':'block'};async function load(){if(busy)return;busy=true;$('refresh').disabled=true;try{const d=await api({action:'list',kind,search:$('search').value.trim(),igreja_id:$('church').value,severity:$('severity').value,status:$('status').value,days:Number($('days').value)});$('open').textContent=d.summary.open_errors;$('actions').textContent=d.summary.actions_today;$('errors').textContent=d.summary.errors_today;$('wa').textContent=d.summary.whatsapp_failed_24h;const cur=$('church').value;$('church').innerHTML='<option value="">Todas as igrejas</option>'+d.churches.map(c=>`<option value="${esc(c.id)}">${esc(c.nome)}</option>`).join('');$('church').value=cur;render(d.items)}catch(e){$('list').innerHTML=`<div class="empty">⚠️ ${esc(e.message)}</div>`}finally{busy=false;$('refresh').disabled=false}}window.resolveLog=async id=>{const note=prompt('Observação da correção (opcional):','')??null;if(note===null)return;await api({action:'resolve',id,status:'resolved',note});load()};window.reopenLog=async id=>{if(!confirm('Reabrir este erro?'))return;await api({action:'resolve',id,status:'open'});load()};document.querySelectorAll('.chip').forEach(b=>b.onclick=()=>{document.querySelectorAll('.chip').forEach(x=>x.classList.remove('active'));b.classList.add('active');kind=b.dataset.kind;load()});$('refresh').onclick=load;$('apply').onclick=load;$('search').addEventListener('keydown',e=>{if(e.key==='Enter')load()});setInterval(load,30000);load();</script></body></html>'''
(root/'master-logs.html').write_text(html,encoding='utf-8')

